eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   CreativeDirector: () => (/* binding */ CreativeDirector)\n/* harmony export */ });\nclass CreativeDirector {\n    static createPlan(params) {\n        const { profile, product, prompt, objective = \"conversao\", funnelStage = \"meio\", format = \"reels\", targetDuration = 24 } = params;\n        const planId = `plan_${Date.now()}_${Math.random().toString(36).substring(2, 6)}`;\n        const prodName = product ? product.name : \"solu\\xe7\\xe3o apresentada\";\n        const prodBrand = product ? product.brand : \"marca\";\n        // Hook based on funnel\n        let hook = \"\";\n        if (funnelStage === \"topo\") {\n            hook = `Você comete esse erro todos os dias sem perceber?`;\n        } else if (funnelStage === \"meio\") {\n            hook = `Depois que descobri ${prodName}, minha rotina nunca mais foi a mesma.`;\n        } else {\n            hook = `Se você ainda não tem ${prodName}, aqui está o motivo exato pelo qual você precisa dele hoje.`;\n        }\n        // Scenes breakdown\n        const scenes = [\n            {\n                sceneNumber: 1,\n                title: \"Cena 1: O Hook Magn\\xe9tico & Quebra de Padr\\xe3o\",\n                durationSeconds: 4,\n                visualPrompt: `Close-up dinâmico de ${profile.name} olhando diretamente para a câmera com expressão intrigante em ambiente refinado. Iluminação suave com foco nos olhos.`,\n                cameraMovement: \"Zoom-in lento e sutil com estabiliza\\xe7\\xe3o fluida.\",\n                lightingStyle: \"Golden hour suave com luz de recorte nos ombros.\",\n                narrationScript: `${hook}`,\n                productInteraction: product ? `Segura sutilmente o ${product.name} em primeiro plano sem cobrir o rosto.` : \"Gesto acolhedor com as m\\xe3os.\",\n                characterAction: \"Olhar confiante para a c\\xe2mera, quebrando a quarta parede.\",\n                status: \"completed\"\n            },\n            {\n                sceneNumber: 2,\n                title: \"Cena 2: Demonstra\\xe7\\xe3o de Benef\\xedcio & Prova Visual\",\n                durationSeconds: 14,\n                visualPrompt: `Plano médio de ${profile.name} demonstrando os diferenciais práticos do ${prodName}. Destaque para textura, qualidade dos materiais e acabamento premium.`,\n                cameraMovement: \"Panor\\xe2mica lateral suave com desfoque de fundo (bokeh).\",\n                lightingStyle: \"Luz difusa de est\\xfadio com reflexos realistas no produto.\",\n                narrationScript: product ? `O diferencial do ${product.name} da ${prodBrand} é que ele entrega ${product.dna.mainBenefits[0] || \"resultados imediatos\"} e resolve ${product.dna.problemSolved || \"a sua maior dor\"}. Olha essa textura e a qualidade impecável.` : `A qualidade de vida muda quando você foca no que realmente importa e escolhe ferramentas comprovadas.`,\n                productInteraction: product ? `Mostra os detalhes do ${product.name} em close-up destacando ${product.dna.keyFeatures.slice(0, 2).join(\" e \")}.` : \"Gesticula\\xe7\\xe3o explicativa.\",\n                characterAction: \"Express\\xe3o de aprova\\xe7\\xe3o sincera e sorriso natural.\",\n                status: \"pending\"\n            },\n            {\n                sceneNumber: 3,\n                title: \"Cena 3: Fechamento com Oferta Irresist\\xedvel & CTA\",\n                durationSeconds: 6,\n                visualPrompt: `Enquadramento 3/4 com ${profile.name} segurando o produto e apontando suavemente para a chamada de ação na tela.`,\n                cameraMovement: \"C\\xe2mera fixa estabilizada com profundidade de campo rasa.\",\n                lightingStyle: \"Ilumina\\xe7\\xe3o premium contrastada.\",\n                narrationScript: `${profile.dna.mainCTA || \"Toque no link abaixo para garantir o seu com condi\\xe7\\xe3o especial.\"}`,\n                productInteraction: product ? `Apresenta o ${product.name} ao lado do rosto com elegância.` : \"Gesto convidativo.\",\n                characterAction: \"Sorriso final e convite direto.\",\n                status: \"pending\"\n            }\n        ];\n        const fullScript = scenes.map((s)=>`[${s.title}]\\n${s.narrationScript}`).join(\"\\n\\n\");\n        const ctaText = profile.dna.mainCTA || \"Clique no link da bio e garanta agora!\";\n        const captionText = `${hook}\\n\\n${product ? `O ${product.name} se tornou indispensável para quem busca ${product.dna.desireExploited || \"m\\xe1xima qualidade\"}.` : \"Dica indispens\\xe1vel para o seu dia a dia.\"}\\n\\n👉 ${ctaText}\\n\\n#${profile.name.replace(/\\s+/g, \"\")} #${prodName.replace(/\\s+/g, \"\")} #Recomendacao #Qualidade #SaaS`;\n        return {\n            id: planId,\n            profileId: profile.id,\n            productId: product?.id,\n            format,\n            objective,\n            funnelStage,\n            targetDurationSeconds: targetDuration,\n            hook,\n            creativeAngle: \"Storytelling Sensorial + Prova Visual\",\n            fullScript,\n            scenes,\n            ctaText,\n            captionText,\n            hashtags: [\n                `#${profile.name.replace(/\\s+/g, \"\")}`,\n                \"#ProfileDark\",\n                \"#HighConverting\",\n                \"#IA\"\n            ],\n            thumbnailPrompt: `Close-up cinematográfico de ${profile.name} com iluminação 4K e produto em destaque.`,\n            estimatedCredits: Math.round(targetDuration * 3.5),\n            createdAt: new Date().toISOString()\n        };\n    }\n}\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/lib/ai/creative-director.ts\n");

